create or replace function public.admin_visual_asset_manifest() returns table(requirement_id uuid,master_template_id text,asset_category text,asset_subcategory text,anatomical_location text,asset_name text,variant_number integer,required_canvas_width integer,required_canvas_height integer,expected_file_type text,expected_alpha_rules text,current_status text,suggested_filename text) language plpgsql stable security definer set search_path=public as $$begin perform require_admin();return query select r.id,r.body_template_key,r.category,r.trait_key,r.anatomical_position,t.display_name,r.variant,r.canvas_width,r.canvas_height,'PNG or WebP','Transparent overlay on exact registered master canvas; no opaque background',r.status,replace(r.body_template_key,'master_','')||'_'||r.category||'_'||r.trait_key||case when r.anatomical_position is null then '' else '_'||lower(r.anatomical_position)end||'_'||lpad(r.variant::text,2,'0')||'.png' from horse_visual_asset_requirements r join equine_visual_taxonomy t on t.category=r.category and t.trait_key=r.trait_key order by r.body_template_key,r.category,t.sort_order,r.anatomical_position,r.variant;end$$;

create or replace function public.admin_register_visual_asset(p_requirement uuid,p_asset_key text,p_image_url text,p_width integer,p_height integer,p_file_type text,p_file_size integer) returns uuid language plpgsql security definer set search_path=public as $$declare r horse_visual_asset_requirements;a uuid;m horse_visual_assets;begin perform require_admin();select * into r from horse_visual_asset_requirements where id=p_requirement for update;if not found then raise exception 'Visual requirement not found';end if;if lower(p_file_type)not in('image/png','image/webp')then raise exception 'Asset must be PNG or WebP';end if;if p_file_size<=0 or p_file_size>10485760 then raise exception 'Asset must be under 10 MB';end if;if p_width<>r.canvas_width or p_height<>r.canvas_height then raise exception 'Asset canvas must be exactly % x %',r.canvas_width,r.canvas_height;end if;select * into m from horse_visual_assets where asset_key=r.body_template_key;if not found then raise exception 'Registered body master not found';end if;insert into horse_visual_assets(asset_key,asset_type,breed,sex,phenotype_key,marking_key,leg_position,image_url,z_index,status,active,review_notes,created_by,body_template_key,canvas_width,canvas_height)values(left(p_asset_key,120),r.category,m.breed,m.sex,case when r.category in('base_coat','modifier','dapple','mane','tail')then r.trait_key end,case when r.category in('face_marking','leg_marking','pattern','pinto_pattern','leopard_complex')then r.trait_key end,case r.anatomical_position when 'LF'then'left_front'when'RF'then'right_front'when'LH'then'left_hind'when'RH'then'right_hind'end,left(p_image_url,2048),50,'pending',false,'Human-supplied asset awaiting Owner review',auth.uid(),r.body_template_key,p_width,p_height)returning id into a;update horse_visual_asset_requirements set asset_id=a,status='review',updated_at=now()where id=r.id;return a;end$$;
revoke all on function public.admin_visual_asset_manifest(),public.admin_register_visual_asset(uuid,text,text,integer,integer,text,integer) from public;
grant execute on function public.admin_visual_asset_manifest(),public.admin_register_visual_asset(uuid,text,text,integer,integer,text,integer) to authenticated;
